-- Verify the insertion
SELECT 
  COUNT(*) as total_records,
  COUNT(DISTINCT (submission_metadata->>'item_name')) as unique_items,
  SUM((submission_metadata->'details'->>'quantity')::numeric) as total_quantity,
  SUM((submission_metadata->'details'->>'total_value')::numeric) as total_value
FROM roleplay_task_records
WHERE submission_type = 'inventory'
  AND submission_metadata->>'source' = 'backstage_initialization';

-- Check inventory view
SELECT 
  COUNT(*) as total_items,
  COUNT(*) FILTER (WHERE quantity > 0) as items_with_quantity
FROM roleplay_inventory_fifo_view;